#!/usr/bin/env sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Generated by build.py from recipe.yml for recipe ftp-see-which-command-broke-a-transfer. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p site/outbox site/inbox plain/outbox
cat > nightly.csv <<'EOF'
id,total
1,42
EOF
printf '%s\n' 'Uploads land here.' > site/outbox/README.txt
cat > site/inbox/orders.csv <<'EOF'
order,qty
7,3
EOF
printf '%s\n' 'Uploads land here.' > plain/outbox/README.txt
cat > job.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# job.sh FTP-URL: the FTP job. It uploads nightly.csv to outbox/ under the URL (ending in /), then fetches
# inbox/orders.csv. A failed step is curl's exit code, and the job stops there.
curl -sS -T nightly.csv "${1}outbox/nightly.csv" || exit
curl -sS -o orders.csv "${1}inbox/orders.csv"
EOF
cat > settled.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# settled.sh LOG: waits until every exchange surl's log says was opened has ended, so the log holds the whole
# of each one. It gives up after 5 seconds, leaving the log as it is.
tries=0
while [ "$(grep -c ' opened: ' "$1")" -gt "$(grep -c ' ended; ' "$1")" ] && [ "$tries" -lt 25 ]; do
  sleep 0.2
  tries=$((tries + 1))
done
EOF
cat > failed-sessions.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# failed-sessions.sh LOG: reads surl's verbose log and prints each session (exchange) that ended on a failure:
# the last command the client sent before it quit or the connection closed, and the reply that ended it, a 4xx
# or 5xx, or "no reply". A line surl logged about that command follows, if there is one. Bytes on a data
# connection are not commands and are skipped. Exit 1 when no session failed.
tr -d '\r' < "$1" | awk '
  { n = substr($1, 2); text = substr($0, length($1) + 4); sub(/\\r\\n$/, "", text) }
  $2 == "*" && $3 == "Data" && $5 == "opened:" { data[n] = 1; next }
  $2 == "*" && $3 == "Data" && $5 == "closed." { data[n] = 0; next }
  $2 == "*" && $3 == "Exchange" && $5 == "ended;" {
    if (cmd[n] != "" && (reply[n] == "" || reply[n] ~ /^[45]/)) {
      print "exchange " n ": " cmd[n] " -> " (reply[n] == "" ? "no reply" : reply[n])
      if (note[n] != "") print "  surl: " note[n]
      failed = 1
    }
    next
  }
  quit[n] { next }
  $2 == "*" && cmd[n] != "" && note[n] == "" { note[n] = text; next }
  $2 == "<" && !data[n] {
    if (text == "QUIT") { quit[n] = 1 } else { cmd[n] = text; reply[n] = ""; note[n] = "" }
    next
  }
  $2 == ">" && cmd[n] != "" && $3 ~ /^[1-5][0-9][0-9]$/ { reply[n] = text }
  END { if (!failed) { print "no failed session in the log"; exit 1 } }'
EOF
surl -v --log-file job.log --allow-anonymous --allow-uploads --fault "error;scheme=ftp;command=STOR;path=/outbox;reply=451 Local error in processing;times=1" --fault "drop;stage=command;command=RETR;path=/inbox;times=1" --directory site ftp://127.0.0.1:8080/ &
surl -v --log-file plain.log --allow-anonymous --directory plain ftp://127.0.0.1:8081/ &
surl --allow-uploads ftp://127.0.0.1:8082/ &
sleep 1
sh settled.sh job.log && sh failed-sessions.sh job.log
kill $(jobs -p)
